"""Regenerate seed_data.sql from untouched CSVs; blank cells become SQL NULL."""
import csv
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def generate_seed():
    statements = [
        "-- Generated by python sql/build_seed.py from data/*.csv; do not edit.",
        "PRAGMA foreign_keys = ON;",
        "BEGIN TRANSACTION;",
        "DELETE FROM orders;",
        "DELETE FROM products;",
        "DELETE FROM customers;",
    ]
    for table in ("customers", "products", "orders"):
        with (ROOT / "data" / f"{table}.csv").open(newline="", encoding="utf-8") as handle:
            reader = csv.DictReader(handle)
            columns = ", ".join(reader.fieldnames)
            for row in reader:
                values = ["NULL" if value == "" else "'" + value.replace("'", "''") + "'"
                          for value in row.values()]
                statements.append(f"INSERT INTO {table} ({columns}) VALUES ({', '.join(values)});")
    statements.append("COMMIT;")
    return "\n".join(statements) + "\n"


if __name__ == "__main__":
    path = ROOT / "sql" / "seed_data.sql"
    path.write_text(generate_seed(), encoding="utf-8")
    print(f"Wrote {path}")
